# Token-Bucket Rate Limiter in TypeScript

The limiter below keeps one bucket per key. It meets the four requirements like this:

- **Continuous refill.** Each bucket stores `tokens` and `updatedAt`. On every access it adds `elapsed × rate`, capped at capacity. There are no timers and no ticks, and fractional tokens carry over.
- **Concurrency safety.** Each read, refill and write happens in one synchronous block with no `await` in the middle. Node never interleaves other code inside such a block, so concurrent callers cannot race.
- **Fair async waiting.** `acquire()` reserves tokens right away, which can push the balance negative, and then sleeps until that debt is repaid. Concurrent waiters are therefore served in FIFO order without polling. If the wait is aborted, the reserved tokens are refunded.
- **Lossless idle eviction.** A full bucket behaves exactly like a brand-new one, so deleting it changes nothing. A sweep removes full buckets at most once per `sweepIntervalMs`. The sweep runs lazily during calls, so there are no `setInterval` handles to clean up. An optional `maxKeys` cap evicts the least-recently-used bucket as a hard memory bound.

## `src/token-bucket.ts`

```typescript
import { setTimeout as delay } from 'node:timers/promises';

/** Injectable time source. `now()` must be monotonic milliseconds. */
export interface Clock {
  now(): number;
  sleep(ms: number, signal?: AbortSignal): Promise<void>;
}

export const systemClock: Clock = {
  now: () => performance.now(), // monotonic, unaffected by wall-clock changes
  sleep: (ms, signal) => delay(ms, undefined, { signal }),
};

export interface RateLimiterOptions {
  /** Maximum burst size (bucket capacity). */
  capacity: number;
  /** Continuous refill rate, in tokens per second. */
  refillPerSecond: number;
  /** Hard cap on tracked keys; least-recently-used is evicted beyond it. Default: Infinity. */
  maxKeys?: number;
  /** Minimum time between idle sweeps. Default: 60_000 ms. */
  sweepIntervalMs?: number;
  clock?: Clock;
}

export interface AcquireOptions {
  signal?: AbortSignal;
  /** Reject immediately (without reserving) if the wait would exceed this. Default: Infinity. */
  maxWaitMs?: number;
}

export interface RateLimitResult {
  allowed: boolean;
  /** Whole tokens left after this call. */
  remaining: number;
  /** 0 if allowed; otherwise ms until `cost` tokens will be available. */
  retryAfterMs: number;
}

export class RateLimitExceededError extends Error {
  constructor(readonly retryAfterMs: number) {
    super(`Rate limit exceeded; retry after ${retryAfterMs} ms`);
    this.name = 'RateLimitExceededError';
  }
}

interface Bucket {
  tokens: number;    // may be negative while acquire() reservations are outstanding
  updatedAt: number; // clock time at which `tokens` was last brought up to date
}

/** Absorbs floating-point drift, e.g. 0.9999999999 tokens counts as 1. */
const EPSILON = 1e-9;

export class TokenBucketRateLimiter {
  readonly capacity: number;
  private readonly ratePerMs: number;
  private readonly maxKeys: number;
  private readonly sweepIntervalMs: number;
  private readonly clock: Clock;
  /** Map iteration order = insertion order, which we keep as LRU → MRU. */
  private readonly buckets = new Map<string, Bucket>();
  private lastSweep: number;

  constructor(opts: RateLimiterOptions) {
    const {
      capacity,
      refillPerSecond,
      maxKeys = Infinity,
      sweepIntervalMs = 60_000,
      clock = systemClock,
    } = opts;

    if (!(capacity > 0) || !Number.isFinite(capacity)) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (!(refillPerSecond > 0) || !Number.isFinite(refillPerSecond)) {
      throw new RangeError('refillPerSecond must be a positive finite number');
    }
    if (!(maxKeys >= 1)) throw new RangeError('maxKeys must be >= 1');
    if (!(sweepIntervalMs >= 0)) throw new RangeError('sweepIntervalMs must be >= 0');

    this.capacity = capacity;
    this.ratePerMs = refillPerSecond / 1000;
    this.maxKeys = maxKeys;
    this.sweepIntervalMs = sweepIntervalMs;
    this.clock = clock;
    this.lastSweep = clock.now();
  }

  /** Number of keys currently tracked. */
  get size(): number {
    return this.buckets.size;
  }

  /** Non-blocking: take `cost` tokens if available. Atomic within the process. */
  tryConsume(key: string, cost = 1): RateLimitResult {
    this.assertCost(cost);
    const now = this.clock.now();
    this.maybeSweep(now);
    const b = this.touch(key, now);

    const retryAfterMs = this.msUntilAvailable(b, cost);
    if (retryAfterMs === 0) {
      b.tokens -= cost;
      return { allowed: true, remaining: this.whole(b.tokens), retryAfterMs: 0 };
    }
    return { allowed: false, remaining: this.whole(b.tokens), retryAfterMs };
  }

  /**
   * Wait until `cost` tokens are available, then take them.
   * Tokens are reserved immediately, so concurrent callers are served FIFO
   * and the limiter never admits more than the configured rate.
   */
  async acquire(key: string, cost = 1, opts: AcquireOptions = {}): Promise<void> {
    this.assertCost(cost);
    const { signal, maxWaitMs = Infinity } = opts;
    signal?.throwIfAborted();

    // --- synchronous critical section: no await until the reservation is made ---
    const now = this.clock.now();
    this.maybeSweep(now);
    const b = this.touch(key, now);
    const waitMs = this.msUntilAvailable(b, cost);
    if (waitMs > maxWaitMs) throw new RateLimitExceededError(waitMs);
    b.tokens -= cost; // reserve (may go negative = debt)
    // --- end critical section ---

    if (waitMs === 0) return;
    try {
      await this.clock.sleep(waitMs, signal);
    } catch (err) {
      this.refund(key, cost);
      throw err;
    }
  }

  /** Forget a key entirely (it will start full next time). */
  reset(key: string): void {
    this.buckets.delete(key);
  }

  /** Evict all buckets that have refilled to capacity. Returns the number evicted. */
  sweep(): number {
    return this.sweepAt(this.clock.now());
  }

  // ---------------------------------------------------------------------------

  private assertCost(cost: number): void {
    if (!(cost > 0) || cost > this.capacity) {
      throw new RangeError(`cost must be in (0, ${this.capacity}]; got ${cost}`);
    }
  }

  /** Get-or-create the bucket, bring it up to date, and mark it most-recently-used. */
  private touch(key: string, now: number): Bucket {
    let b = this.buckets.get(key);
    if (b) {
      this.buckets.delete(key); // re-inserted below → moves to MRU end
      this.refill(b, now);
    } else {
      if (this.buckets.size >= this.maxKeys) this.evictLru();
      b = { tokens: this.capacity, updatedAt: now };
    }
    this.buckets.set(key, b);
    return b;
  }

  private refill(b: Bucket, now: number): void {
    const elapsed = now - b.updatedAt;
    if (elapsed > 0) {
      b.tokens = Math.min(this.capacity, b.tokens + elapsed * this.ratePerMs);
      b.updatedAt = now;
    }
  }

  private refund(key: string, cost: number): void {
    const b = this.buckets.get(key);
    if (!b) return; // evicted under maxKeys pressure; nothing to refund
    this.refill(b, this.clock.now());
    b.tokens = Math.min(this.capacity, b.tokens + cost);
  }

  private msUntilAvailable(b: Bucket, cost: number): number {
    const deficit = cost - b.tokens;
    return deficit <= EPSILON ? 0 : Math.ceil(deficit / this.ratePerMs);
  }

  private whole(tokens: number): number {
    return Math.max(0, Math.floor(tokens + EPSILON));
  }

  private maybeSweep(now: number): void {
    if (now - this.lastSweep >= this.sweepIntervalMs) this.sweepAt(now);
  }

  /** Lossless: a full bucket is indistinguishable from a freshly created one. */
  private sweepAt(now: number): number {
    this.lastSweep = now;
    let evicted = 0;
    for (const [key, b] of this.buckets) {
      const projected = b.tokens + Math.max(0, now - b.updatedAt) * this.ratePerMs;
      if (projected >= this.capacity - EPSILON) {
        this.buckets.delete(key); // deleting during Map iteration is safe
        evicted++;
      }
    }
    return evicted;
  }

  /** Lossy: forgets the LRU key's state (it gets a fresh, full bucket if it returns). */
  private evictLru(): void {
    const oldest = this.buckets.keys().next();
    if (!oldest.done) this.buckets.delete(oldest.value);
  }
}
