## `test/token-bucket.test.ts`

```typescript
import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  TokenBucketRateLimiter,
  RateLimitExceededError,
  type Clock,
} from '../src/token-bucket.ts';

// --- Fake clock ---------------------------------------------------------------

interface Timer { at: number; seq: number; fire: () => void }

const flush = () => new Promise<void>((r) => setImmediate(r));

class FakeClock implements Clock {
  private t = 0;
  private seq = 0;
  private timers: Timer[] = [];

  now(): number {
    return this.t;
  }

  sleep(ms: number, signal?: AbortSignal): Promise<void> {
    return new Promise((resolve, reject) => {
      if (signal?.aborted) return reject(signal.reason);
      const timer: Timer = { at: this.t + Math.max(0, ms), seq: this.seq++, fire: () => {} };
      const onAbort = () => {
        this.timers = this.timers.filter((x) => x !== timer);
        reject(signal!.reason);
      };
      timer.fire = () => {
        signal?.removeEventListener('abort', onAbort);
        resolve();
      };
      signal?.addEventListener('abort', onAbort, { once: true });
      this.timers.push(timer);
    });
  }

  /** Advance time, firing due timers in order and letting their continuations run. */
  async advance(ms: number): Promise<void> {
    const target = this.t + ms;
    for (;;) {
      this.timers.sort((a, b) => a.at - b.at || a.seq - b.seq);
      const next = this.timers[0];
      if (!next || next.at > target) break;
      this.timers.shift();
      this.t = next.at;
      next.fire();
      await flush();
    }
    this.t = target;
    await flush();
  }
}

function setup(overrides: Partial<ConstructorParameters<typeof TokenBucketRateLimiter>[0]> = {}) {
  const clock = new FakeClock();
  const limiter = new TokenBucketRateLimiter({
    capacity: 10,
    refillPerSecond: 10,
    sweepIntervalMs: Infinity,
    clock,
    ...overrides,
  });
  return { clock, limiter };
}

// --- Basic semantics ----------------------------------------------------------

test('starts full, allows a burst up to capacity, then denies', () => {
  const { limiter } = setup();
  for (let i = 0; i < 10; i++) {
    const r = limiter.tryConsume('k');
    assert.equal(r.allowed, true);
    assert.equal(r.remaining, 9 - i);
  }
  const denied = limiter.tryConsume('k');
  assert.equal(denied.allowed, false);
  assert.equal(denied.remaining, 0);
  assert.ok(denied.retryAfterMs >= 100 && denied.retryAfterMs <= 101); // 1 token @ 10/s
});

test('refills continuously, keeping fractional tokens between calls', async () => {
  const { clock, limiter } = setup();
  for (let i = 0; i < 10; i++) limiter.tryConsume('k');

  await clock.advance(150); // +1.5 tokens
  assert.equal(limiter.tryConsume('k').allowed, true); // 0.5 left
  const r = limiter.tryConsume('k');
  assert.equal(r.allowed, false);
  assert.ok(r.retryAfterMs >= 50 && r.retryAfterMs <= 51);

  await clock.advance(25); // 0.75 — not yet
  assert.equal(limiter.tryConsume('k').allowed, false);
  await clock.advance(25); // 1.0 — the fractional 0.75 was kept
  assert.equal(limiter.tryConsume('k').allowed, true);
});

test('never refills above capacity', async () => {
  const { clock, limiter } = setup();
  limiter.tryConsume('k');
  await clock.advance(1_000_000);
  for (let i = 0; i < 10; i++) assert.equal(limiter.tryConsume('k').allowed, true);
  assert.equal(limiter.tryConsume('k').allowed, false);
});

test('keys are independent', () => {
  const { limiter } = setup({ capacity: 1 });
  assert.equal(limiter.tryConsume('a').allowed, true);
  assert.equal(limiter.tryConsume('a').allowed, false);
  assert.equal(limiter.tryConsume('b').allowed, true);
});

test('supports weighted costs and validates them', () => {
  const { limiter } = setup();
  assert.equal(limiter.tryConsume('k', 7).allowed, true);
  assert.equal(limiter.tryConsume('k', 4).allowed, false);
  assert.equal(limiter.tryConsume('k', 3).allowed, true);
  assert.throws(() => limiter.tryConsume('k', 11), RangeError);
  assert.throws(() => limiter.tryConsume('k', 0), RangeError);
  assert.throws(() => limiter.tryConsume('k', NaN), RangeError);
});

test('rejects invalid options', () => {
  assert.throws(() => new TokenBucketRateLimiter({ capacity: 0, refillPerSecond: 1 }), RangeError);
  assert.throws(() => new TokenBucketRateLimiter({ capacity: 1, refillPerSecond: -1 }), RangeError);
  assert.throws(
    () => new TokenBucketRateLimiter({ capacity: 1, refillPerSecond: 1, maxKeys: 0 }),
    RangeError,
  );
});

// --- Eviction -----------------------------------------------------------------

test('lazy sweep evicts only buckets that have fully refilled', async () => {
  const { clock, limiter } = setup({ capacity: 5, refillPerSecond: 1, sweepIntervalMs: 1000 });

  for (let i = 0; i < 5; i++) limiter.tryConsume('a'); // drained at t=0
  await clock.advance(4000); // 'a' has 4/5
  limiter.tryConsume('b'); // triggers sweep; 'a' not full → kept
  assert.equal(limiter.size, 2);

  await clock.advance(1000); // 'a' 5/5, 'b' 5/5
  limiter.tryConsume('c'); // sweep evicts a and b, then creates c
  assert.equal(limiter.size, 1);

  // Eviction was lossless: 'a' behaves exactly as a full bucket would.
  for (let i = 0; i < 5; i++) assert.equal(limiter.tryConsume('a').allowed, true);
  assert.equal(limiter.tryConsume('a').allowed, false);
});

test('manual sweep() returns number of evicted keys', async () => {
  const { clock, limiter } = setup({ capacity: 2, refillPerSecond: 1 });
  for (const k of ['a', 'b', 'c']) limiter.tryConsume(k);
  limiter.tryConsume('c'); // c is now 0/2, a and b are 1/2
  await clock.advance(1000); // a,b full; c 1/2
  assert.equal(limiter.sweep(), 2);
  assert.equal(limiter.size, 1);
});

test('memory stays bounded across many one-off keys', async () => {
  const { clock, limiter } = setup({ capacity: 1, refillPerSecond: 1, sweepIntervalMs: 1000 });
  for (let i = 0; i < 10_000; i++) {
    limiter.tryConsume(`user-${i}`);
    await clock.advance(1); // each key fully refills 1s after use
  }
  assert.ok(limiter.size <= 2000, `size was ${limiter.size}`);
});

test('maxKeys evicts the least-recently-used key', () => {
  const { limiter } = setup({ capacity: 1, refillPerSecond: 1, maxKeys: 2 });
  limiter.tryConsume('a'); // [a]
  limiter.tryConsume('b'); // [a, b]
  limiter.tryConsume('a'); // denied, touch → [b, a]
  limiter.tryConsume('c'); // evicts b → [a, c]
  assert.equal(limiter.size, 2);
  assert.equal(limiter.tryConsume('a').allowed, false); // retained → [c, a]
  assert.equal(limiter.tryConsume('b').allowed, true); // was evicted → fresh
  assert.equal(limiter.size, 2);
});

// --- Concurrency ----------------------------------------------------------------

test('interleaved async callers cannot over-consume', async () => {
  const { limiter } = setup();
  const results = await Promise.all(
    Array.from({ length: 100 }, async (_, i) => {
      for (let j = 0; j < i % 5; j++) await flush(); // scramble ordering
      return limiter.tryConsume('k').allowed;
    }),
  );
  assert.equal(results.filter(Boolean).length, 10);
});

test('concurrent acquire() calls are served FIFO at exactly the refill rate', async () => {
  const { clock, limiter } = setup({ capacity: 1, refillPerSecond: 1 });
  const done: Array<[number, number]> = [];
  const all = Promise.all(
    [0, 1, 2, 3].map((i) => limiter.acquire('k').then(() => done.push([i, clock.now()]))),
  );

  await clock.advance(3000);
  await all;
  assert.deepEqual(done, [[0, 0], [1, 1000], [2, 2000], [3, 3000]]);

  // All refilled tokens were spent by the waiters; nothing extra is admitted.
  assert.equal(limiter.tryConsume('k').allowed, false);
});

test('acquire() with maxWaitMs rejects without reserving', async () => {
  const { clock, limiter } = setup({ capacity: 1, refillPerSecond: 1 });
  await limiter.acquire('k');
  await assert.rejects(
    limiter.acquire('k', 1, { maxWaitMs: 500 }),
    (err: unknown) => err instanceof RateLimitExceededError && err.retryAfterMs === 1000,
  );
  await clock.advance(1000);
  assert.equal(limiter.tryConsume('k').allowed, true); // the rejected call took nothing
});

test('aborting acquire() refunds its reservation', async () => {
  const { clock, limiter } = setup({ capacity: 1, refillPerSecond: 1 });
  await limiter.acquire('k'); // tokens: 0
  const ac = new AbortController();
  const pending = limiter.acquire('k', 1, { signal: ac.signal }); // tokens: -1 (reserved)
  ac.abort();
  await assert.rejects(pending);

  await clock.advance(1000);
  assert.equal(limiter.tryConsume('k').allowed, true); // would be denied without the refund
});

test('already-aborted signal rejects immediately', async () => {
  const { limiter } = setup();
  await assert.rejects(limiter.acquire('k', 1, { signal: AbortSignal.abort() }));
});
```

Run the tests with:

```bash
npx tsx --test test/token-bucket.test.ts
# or, on Node ≥ 22.6:
node --experimental-strip-types --test test/token-bucket.test.ts
```

## Design notes

**Refill formula.** On each access the bucket is updated as

$$\text{tokens} \leftarrow \min\!\big(C,\ \text{tokens} + (t_{\text{now}} - t_{\text{updated}})\cdot r\big)$$

This costs O(1) per call and needs no background timers.

**Why eviction is safe.** A bucket is full once $\text{tokens} + \Delta t \cdot r \ge C$. A full bucket is identical to a new one, so the sweep never loosens the limit.

**What `maxKeys` trades off.** It is a memory backstop. When it evicts a bucket that is not full, that key's history is forgotten, and the key could get one extra burst. Size `maxKeys` well above your expected number of active keys.

**Sweep cost.** Each sweep is O(n) in tracked keys, but it runs at most once per interval. One million keys take roughly tens of milliseconds to sweep. If that pause matters, lower `sweepIntervalMs`, or switch to an incremental sweep that checks a fixed number of entries per call.

**Clock choice.** The default clock uses `performance.now()`. It is monotonic, so changes to the system time cannot refill or freeze buckets.

**Scope.** The limiter is safe only within a single process. Worker threads, `cluster` workers, or multiple instances behind a load balancer each keep their own buckets. For limits shared across them, use the same algorithm in a shared store, such as a Redis Lua script that runs the same refill-and-consume logic atomically.
